const express = require('express');
const diagnostics_channel = require('node:diagnostics_channel');
const { AsyncLocalStorage } = require('node:async_hooks');
const { authenticate } = require('./auth');

const app = express();
const asyncContext = new AsyncLocalStorage();
const egressChannel = diagnostics_channel.channel('undici:request:create');

const egressAuditLogs = new Map();

egressChannel.subscribe((requestData) => {
  const store = asyncContext.getStore();
  egressAuditLogs.set(requestData.requestId, {
    organizationId: store?.organizationId,
    url: requestData.url,
    headers: requestData.headers,
    body: requestData.body,
    initiatedAt: new Date()
  });
});

app.use(authenticate);
app.use((req, res, next) => {
  asyncContext.run({ organizationId: req.user?.organizationId, userId: req.user?.id }, next);
});

app.get('/api/debug/egress-requests/:requestId', (req, res) => {
  const entry = egressAuditLogs.get(req.params.requestId);
  if (!entry) {
    return res.status(404).json({ error: 'Egress request record expired or not found' });
  }

  // Verify that the egress request was dispatched by the authenticated user's organization
  if (entry.organizationId !== req.user.organizationId) {
    return res.status(403).json({ error: 'Forbidden: request record belongs to a different organization' });
  }

  res.json({
    requestId: req.params.requestId,
    url: entry.url,
    initiatedAt: entry.initiatedAt
  });
});

app.listen(9102);
